package au.aumanet.app;
import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
/** Only complete, reverified digest-addressed images are offered to installation. */
final class NodeUpdateCache {
 static final class Package{final NodeReleaseIndex.Release release;final File image;Package(NodeReleaseIndex.Release release,File image){this.release=release;this.image=image;}JSONObject json()throws Exception{NodeReleaseManifest m=release.manifest;return new JSONObject().put("packageId",m.id).put("releaseDigest",m.id).put("imageBytes",m.imageBytes).put("verified",true).put("release",m.json(release.notes));}}
 private final File directory;private final LinkedHashMap<String,Package> packages=new LinkedHashMap<>();private boolean healthy=true;
 NodeUpdateCache(File directory){this.directory=directory;if(!directory.isDirectory()&&!directory.mkdirs()){healthy=false;return;}File[] owned=directory.listFiles();if(owned==null||owned.length>64){healthy=false;return;}for(File f:owned)if(f.getName().matches("[a-f0-9]{32}\\.partial")||f.getName().matches("[a-f0-9]{64}\\.bin")&&!new File(directory,f.getName().replace(".bin",".json")).exists()&&!new File(directory,f.getName().replace(".bin",".json.bak")).exists())if(!f.delete())healthy=false;long used=0;for(File f:owned)if(f.isFile())used+=f.length();if(used>32L*1024*1024){healthy=false;return;}Set<String> names=new HashSet<>();for(File f:owned)if(f.getName().matches("[a-f0-9]{64}\\.json(\\.bak)?"))names.add(f.getName().replace(".bak",""));File[] files=names.stream().map(n->new File(directory,n)).toArray(File[]::new);if(files.length>16){healthy=false;return;}Arrays.sort(files,Comparator.comparingLong(File::lastModified));for(File f:files)try{JSONObject raw=GroupNameJson.object(new String(read(new AtomicFile(f).openRead(),8192),StandardCharsets.UTF_8),8192);GatewayBindingConfig.keys(raw,"manifest","signature","imageUrl","notes","sourceStatus");NodeReleaseIndex.Release r=NodeReleaseIndex.release(raw);NodeReleaseManifest m=r.manifest;if(!f.getName().equals(m.id+".json"))throw new IOException();File image=new File(directory,m.id+".bin");verify(image,m);packages.put(m.id,new Package(r,image));}catch(Exception invalid){healthy=false;}if(packages.size()>4)healthy=false;}
 synchronized boolean healthy(){return healthy;}synchronized JSONArray snapshot()throws Exception{JSONArray out=new JSONArray();for(Package p:packages.values())out.put(p.json());return out;}
 synchronized Package get(String id)throws Exception{Package p=packages.get(id);if(!healthy||p==null)throw new IOException("Verified firmware cache unavailable");verify(p.image,p.release.manifest);return p;}
 File staging(String operation){if(!GroupWire.id(operation))throw new IllegalArgumentException();return new File(directory,operation+".partial");}
 synchronized void commit(NodeReleaseIndex.Release release,File staged)throws Exception{if(!healthy||!staged.getCanonicalFile().getParentFile().equals(directory.getCanonicalFile())||!staged.getName().matches("[a-f0-9]{32}\\.partial"))throw new IOException();verify(staged,release.manifest);NodeReleaseIndex.release(release.raw);while(packages.size()>=4&&!packages.containsKey(release.manifest.id)){Package old=packages.values().iterator().next();File meta=new File(directory,old.release.manifest.id+".json");if(meta.exists()&&!meta.delete()||old.image.exists()&&!old.image.delete())throw new IOException();packages.remove(old.release.manifest.id);}File destination=new File(directory,release.manifest.id+".bin");AtomicFile image=new AtomicFile(destination);FileOutputStream out=null;try{out=image.startWrite();try(InputStream input=new FileInputStream(staged)){byte[] b=new byte[8192];for(int n;(n=input.read(b))!=-1;)out.write(b,0,n);}image.finishWrite(out);out=null;verify(destination,release.manifest);AtomicFile meta=new AtomicFile(new File(directory,release.manifest.id+".json"));try{out=meta.startWrite();out.write(release.raw.toString().getBytes(StandardCharsets.UTF_8));meta.finishWrite(out);out=null;}catch(Exception failed){if(out!=null)meta.failWrite(out);throw failed;}packages.put(release.manifest.id,new Package(release,destination));}catch(Exception failed){healthy=false;if(out!=null)image.failWrite(out);throw failed;}finally{if(staged.exists())staged.delete();}}
 static void verify(File image,NodeReleaseManifest release)throws Exception{if(!image.isFile()||image.length()!=release.imageBytes)throw new IOException("Firmware image is incomplete");MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(image)){byte[] b=new byte[8192];int total=0;for(int n;(n=in.read(b))!=-1;){total+=n;if(total>release.imageBytes)throw new IOException();digest.update(b,0,n);}if(total!=release.imageBytes||!NodeReleaseManifest.hex(digest.digest()).equals(release.imageSha))throw new IOException("Firmware digest verification failed");}NodeFirmwareImage.checked(image,release);}
 static byte[] read(InputStream stream,int max)throws IOException{try(InputStream in=stream;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];for(int n;(n=in.read(b))!=-1;){if(out.size()+n>max)throw new IOException();out.write(b,0,n);}return out.toByteArray();}}
}
